function winOff() {
  try {
    const d = JSON.parse(readFileSync(TRACK, 'utf8'));
    const last = d.samples[d.samples.length-1];
    const elapsed = last.elapsedMs + (Date.now() - Date.parse(last.timestamp));
    return elapsed % 15000;
  } catch { return 0; }
}

async function waitWin() {
  // start dump 0.3-2.5s after a sample so ~9s bury fits in the 15s window
  for (let i = 0; i < 80; i++) {
    const off = winOff();
    if (off >= 300 && off < 2500) return;
    await new Promise(r => setTimeout(r, 150));
  }
}

