import { runScript } from "/app/sdk/runner";

function coinsOf(sdk: any): number {
  return sdk.findInventoryItem(/coins/i)?.count ?? 0;
}

function nearest(sdk: any, re: RegExp) {
  return (sdk.getNearbyNpcs() ?? [])
    .filter((n: any) => re.test(n.name) && n.optionsWithIndex?.some((o: any) => /attack|pickpocket/i.test(o.text)))
    .sort((a: any, b: any) => a.distance - b.distance)[0];
}

