async function pickpocketUntil(n, ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    await bot.dismissBlockingUI();
    const gp = sdk.findInventoryItem(/coins/i)?.count ?? 0;
    if (gp >= n) return gp;
    const t = sdk.findNearbyNpc(/^man$/i);
    if (!t) { await sdk.waitForTicks(2); continue; }
    await bot.pickpocketNpc(t);
  }
  return sdk.findInventoryItem(/coins/i)?.count ?? 0;
}

