async function dialogLoop(prefer, maxTicks) {
  maxTicks = maxTicks || 25;
  const log = [];
  for (let i = 0; i < maxTicks; i++) {
    await bot.dismissBlockingUI();
    const d = sdk.getDialog();
    if (!d || !d.isOpen) {
      await sdk.waitForTicks(2);
      if (!sdk.getDialog() || !sdk.getDialog().isOpen) return log;
      continue;
    }
    const opts = d.options || [];
    log.push(opts.map(o => o.index+':'+o.text).join(' | ') || '(c)');
    let idx = 0;
    for (const re of prefer) {
      const m = opts.find(o => re.test(o.text) && !/continue/i.test(o.text));
      if (m) { idx = m.index; break; }
    }
    if (opts.length === 1 && /continue/i.test(opts[0].text)) idx = 0;
    await sdk.sendClickDialog(idx);
    await sdk.waitForTicks(2);
  }
  return log;
}
